mapper.insert:
INSERT INTO place_reviews (
    place_id, user_id, rating, content, verified_visit, status
) VALUES (
    #{placeId}, #{userId}, #{rating}, #{content},
    COALESCE(#{verifiedVisit}, FALSE), 'VISIBLE'
)

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM itinerary_items ii
    JOIN trip_days td ON td.trip_day_id = ii.trip_day_id
    JOIN trips t ON t.trip_id = td.trip_id
    WHERE ii.place_id = #{placeId}
      AND t.user_id = #{userId}
      AND t.status = 'COMPLETED'
      AND t.deleted_at IS NULL
)

mapper.delete:
DELETE FROM place_reviews
WHERE place_review_id = #{reviewId}
  AND user_id = #{userId}

mapper.update:
UPDATE places
SET average_rating = (
    SELECT ROUND(AVG(rating)::numeric, 2)
    FROM place_reviews
    WHERE place_id = #{placeId}
      AND status = 'VISIBLE'
),
updated_at = CURRENT_TIMESTAMP
WHERE place_id = #{placeId}
